    on conflict(product_id,locale) do nothing;
    insert into public.product_options(product_id,code,name_en,name_ar,position) values(v_product_id,'color','Colour','اللون',1) on conflict(product_id,code) do nothing;
    select id into colour_option_id from public.product_options where product_options.product_id=v_product_id and code='color';
    for colour in select value from jsonb_array_elements(item->'colors') loop
      insert into public.product_option_values(option_id,code,label_en,label_ar,swatch_hex,position)
      values(colour_option_id,colour->>'code',colour->>'label_en',colour->>'label_ar',colour->>'swatch_hex',(colour->>'position')::integer) on conflict(option_id,code) do nothing;
    end loop;
    for image in select value from jsonb_array_elements(item->'images') loop
      insert into public.product_images(product_id,storage_path,alt_en,alt_ar,position,colour_code,width,height)
      values(v_product_id,image->>'storage_path',image->>'alt_en',image->>'alt_ar',(image->>'position')::integer,image->>'colour_code',(image->>'width')::integer,(image->>'height')::integer) on conflict(product_id,storage_path) do nothing;
    end loop;
  end loop;
  if old_order_links <> (select md5(coalesce(jsonb_agg(jsonb_build_array(id,product_id,variant_id) order by id)::text,'')) from public.order_items) or old_order_count <> (select count(*) from public.orders) or old_review_count <> (select count(*) from public.product_reviews) then raise exception 'Historical record verification failed'; end if;
end $kova$;
commit;
select jsonb_build_object('catalog',(select jsonb_agg(jsonb_build_object('id',p.id,'slug',p.slug,'brand',p.brand,'status',p.status,'price_minor',p.base_price_minor,'cod_deposit_minor',p.cod_deposit_minor) order by p.id) from public.products p),'orders',(select count(*) from public.orders),'order_items',(select count(*) from public.order_items),'reviews',(select count(*) from public.product_reviews)) as result;
